import{_ as t,a,o as r,a6 as n}from"./chunks/framework.CJDy2q7X.js";const g=JSON.parse('{"title":"Configuration Slugs (GraphQL)","description":"","frontmatter":{"outline":false,"examples":[{"id":"list-slugs","title":"List all slugs","description":"Discover every configuration slug (section / group key) you can pass to the Values and Update operations.","query":"query AdminConfigurationSlugs {\\n  listAdminConfigurationSlug {\\n    slugs\\n  }\\n}\\n","variables":"{}\\n","response":"{\\n  \\"data\\": {\\n    \\"listAdminConfigurationSlug\\": {\\n      \\"slugs\\": [\\n        {\\n          \\"slug\\": \\"general\\",\\n          \\"name\\": \\"General\\",\\n          \\"sort\\": 1,\\n          \\"hasFields\\": false,\\n          \\"hasChildren\\": true\\n        },\\n        {\\n          \\"slug\\": \\"general.general\\",\\n          \\"name\\": \\"General\\",\\n          \\"sort\\": 1,\\n          \\"hasFields\\": false,\\n          \\"hasChildren\\": true\\n        },\\n        {\\n          \\"slug\\": \\"general.general.locale_options\\",\\n          \\"name\\": \\"Unit Options\\",\\n          \\"sort\\": 1,\\n          \\"hasFields\\": true,\\n          \\"hasChildren\\": false\\n        },\\n        {\\n          \\"slug\\": \\"sales.order_settings\\",\\n          \\"name\\": \\"Order Settings\\",\\n          \\"sort\\": 4,\\n          \\"hasFields\\": false,\\n          \\"hasChildren\\": true\\n        }\\n      ]\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/configuration/slugs.md","filePath":"api/graphql-api/admin/configuration/slugs.md","lastUpdated":1787725411000}'),s={name:"api/graphql-api/admin/configuration/slugs.md"};function o(d,e,i,l,u,h){return r(),a("div",null,e[0]||(e[0]=[n('<h1 id="configuration-slugs-graphql" tabindex="-1">Configuration Slugs (GraphQL) <a class="header-anchor" href="#configuration-slugs-graphql" aria-label="Permalink to &quot;Configuration Slugs (GraphQL)&quot;">​</a></h1><p>Query field: <strong><code>listAdminConfigurationSlug</code></strong>.</p><p>Lists every registered configuration <strong>slug</strong> (a section or group key) so you can discover the valid slugs to pass to the <a href="./values.html">Values</a> and <a href="./update.html">Update</a> operations — without trial and error. See the <a href="./">Configuration overview</a> for how the operations fit together.</p><p>The query exposes one field, <code>slugs</code> — a JSON array. Select it bare; it is not a typed sub-object.</p><h2 id="slug-shape" tabindex="-1">Slug shape <a class="header-anchor" href="#slug-shape" aria-label="Permalink to &quot;Slug shape&quot;">​</a></h2><p>Each entry in <code>slugs[]</code> carries:</p><table tabindex="0"><thead><tr><th>Key</th><th>Meaning</th></tr></thead><tbody><tr><td><code>slug</code></td><td>Dotted key (e.g. <code>sales.order_settings</code>). Pass this to Values / Update.</td></tr><tr><td><code>name</code></td><td>Human-readable label (already translated).</td></tr><tr><td><code>sort</code></td><td>Display order within its parent.</td></tr><tr><td><code>hasFields</code></td><td><code>true</code> when the node holds editable fields directly.</td></tr><tr><td><code>hasChildren</code></td><td><code>true</code> when the node nests further sub-nodes.</td></tr></tbody></table><p>A node where <code>hasFields</code> is <code>true</code> is the level you read values for; a node where only <code>hasChildren</code> is <code>true</code> is a parent you can drill into.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Cause</th><th>Response</th></tr></thead><tbody><tr><td>Unauthenticated</td><td><code>errors[]</code> — admin Bearer token required.</td></tr></tbody></table>',10)]))}const p=t(s,[["render",o]]);export{g as __pageData,p as default};
